291	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
292		app, err := requiredString(doc, "app")
293		if err != nil {
294			return ReleasePlanInput{}, err
295		}
296		revision, err := requiredString(doc, "revision")
297		if err != nil {
298			return ReleasePlanInput{}, err
299		}
300		image, err := requiredString(doc, "image")
301		if err != nil {
302			return ReleasePlanInput{}, err
303		}
304		batchSize, err := positiveInt(doc, "batchSize")
305		if err != nil {
306			return ReleasePlanInput{}, err
307		}
308		spreadBy, err := optionalSpreadBy(doc)
309		if err != nil {
310			return ReleasePlanInput{}, err
311		}
312		clusters, err := parseClusters(doc["clusters"])
313		if err != nil {
314			return ReleasePlanInput{}, err
315		}
316		include, err := parseConditions(doc, "include")
317		if err != nil {
318			return ReleasePlanInput{}, err
319		}
320		exclude, err := parseConditions(doc, "exclude")
321		if err != nil {
322			return ReleasePlanInput{}, err
323		}
324	
325		return ReleasePlanInput{
326			App:       app,
327			Revision:  revision,
328			Image:     image,
329			BatchSize: batchSize,
330			Clusters:  clusters,
331			Include:   include,
332			Exclude:   exclude,
333			SpreadBy:  spreadBy,
334		}, nil
335	}
336	
337	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
338	// string disables fault-domain spreading; a non-string value or a string of
339	// only whitespace is rejected. The tag key is used exactly as written.
340	func optionalSpreadBy(doc map[string]any) (string, error) {
341		v, ok := doc["spreadBy"]
342		if !ok {
343			return "", nil
344		}
345		s, ok := v.(string)
346		if !ok {
347			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
348		}
349		if err := checkSpreadBy(s); err != nil {
350			return "", err
351		}
352		return s, nil
353	}
354	
355	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
356	// tag key: a string of only whitespace can never match a valid tag key.
357	func checkSpreadBy(s string) error {
358		if s != "" && strings.TrimSpace(s) == "" {
359			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
360		}
361		return nil
362	}
363	
364	// ValidateReleaseInput checks that a release configuration is well-formed.
365	// Every string is first required to be legal UTF-8 — app, revision, image,
366	// spreadBy, every candidate's ID and tag keys/values (disabled and
367	// filtered-out candidates included), and every include/exclude condition's
368	// keys and values — because invalid bytes would later be rewritten to "�"
369	// while the plan is written as JSON and could merge two distinct identities
370	// or take part in label matching as an ordinary value. That text check runs
371	// before any business rule, in a fixed order (field order, then candidate
372	// and condition positions from zero, then keys in ascending order), so the
373	// one problem it reports never depends on map iteration. Business
374	// validation then runs as before: app/revision/image are non-empty,
375	// batchSize is a positive integer, spreadBy is empty or a usable tag key
376	// (not whitespace-only), cluster IDs are unique across every candidate
377	// (including disabled and filtered-out clusters), and tag/condition keys
378	// are non-empty. Errors name the field and the position in its list; within
379	// a cluster the ID is checked before its tags, and tag keys are examined in
380	// ascending order so repeated calls report the same error. The input is
381	// never mutated. MakeReleasePlan calls this automatically; library callers
382	// may use it to validate without planning.
383	func ValidateReleaseInput(in ReleasePlanInput) error {
384		if err := validateStrictText(in); err != nil {
385			return err
386		}
387		if strings.TrimSpace(in.App) == "" {
388			return errors.New(`字段 "app" 不能为空或只含空白`)
389		}
390		if strings.TrimSpace(in.Revision) == "" {
391			return errors.New(`字段 "revision" 不能为空或只含空白`)
392		}
393		if strings.TrimSpace(in.Image) == "" {
394			return errors.New(`字段 "image" 不能为空或只含空白`)
395		}
396		if in.BatchSize <= 0 {
397			return errors.New(`字段 "batchSize" 必须是正整数`)
398		}
399		if err := checkSpreadBy(in.SpreadBy); err != nil {
400			return err
401		}
402		ids := newClusterIDSet(len(in.Clusters))
403		for i, c := range in.Clusters {
404			if err := ids.check(i, c.ID); err != nil {
405				return err
406			}
407			if err := validateTagKeys(i, c.Tags); err != nil {
408				return err
409			}
410		}
411		if err := validateConditionKeys("include", in.Include); err != nil {
412			return err
413		}
414		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
415			return err
416		}
417		return nil
418	}
419	
420	// validateTagKeys applies the shared label-key rule to one cluster's tags,
421	// reporting the cluster's position in the candidate list.
422	func validateTagKeys(clusterIndex int, tags map[string]string) error {
423		if hasEmptyLabelKey(tags) {
424			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
425		}
426		return nil
427	}
428	
429	// validateConditionKeys applies the shared condition rules to every condition
430	// in original order, so the first invalid condition is reported.
431	func validateConditionKeys(field string, conds []LabelCondition) error {
432		for i, cond := range conds {
433			if err := validateCondition(field, i, cond); err != nil {
434				return err
435			}
436		}
437		return nil
438	}
439	
440	func requiredString(doc map[string]any, field string) (string, error) {
441		v, ok := doc[field]
442		if !ok {
443			return "", fmt.Errorf("缺少必需字段 %q", field)
444		}
445		s, ok := v.(string)
446		if !ok {
447			return "", fmt.Errorf("字段 %q 必须是字符串", field)
448		}
449		if strings.TrimSpace(s) == "" {
450			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
451		}
452		return s, nil
453	}
454	
455	// positiveInt reads a required field as a positive integer. The literal must
456	// be an integral JSON number whose value is representable in full by the Go
457	// int of the running environment: a value beyond math.MaxInt is rejected here
458	// rather than narrowed by an int() conversion, which on a 32-bit environment
459	// could turn 4294967297 into 1 (or a larger value into zero or a negative
460	// number). No truncation, rounding, default substitution or clamping to the
461	// maximum ever happens — such a value is a configuration error regardless of
462	// what int it would collapse into.
463	func positiveInt(doc map[string]any, field string) (int, error) {
464		v, ok := doc[field]
465		if !ok {
466			return 0, fmt.Errorf("缺少必需字段 %q", field)
467		}
468		n, ok := v.(json.Number)
469		if !ok {
470			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
471		}
472		i, err := n.Int64()
473		if err != nil || i <= 0 || i > math.MaxInt {
474			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
475		}
476		return int(i), nil
477	}
478	
479	func parseClusters(v any) ([]Cluster, error) {
480		if v == nil {
481			return nil, errors.New("缺少必需字段 \"clusters\"")
482		}
483		raw, ok := v.([]any)
484		if !ok {
485			return nil, errors.New("字段 \"clusters\" 必须是数组")
486		}
487		clusters := make([]Cluster, 0, len(raw))
488		ids := newClusterIDSet(len(raw))
489		for i, item := range raw {
490			obj, ok := item.(map[string]any)
491			if !ok {
492				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
493			}
494			id, err := clusterIDFromJSON(obj, i, ids)
495			if err != nil {
496				return nil, err
497			}
498	
499			disabled := false
500			if dv, present := obj["disabled"]; present {
501				b, ok := dv.(bool)
502				if !ok {
503					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
504				}
505				disabled = b
506			}
507	
508			tags := map[string]string{}
509			if tv, present := obj["tags"]; present {
510				tm, ok := tv.(map[string]any)
511				if !ok {
512					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
513				}
514				tags, err = labelsFromJSON(tm,
515					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
516					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
517				)
518				if err != nil {
519					return nil, err
520				}
521			}
522	
523			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
524		}
525		return clusters, nil
526	}
527	
528	// clusterIDFromJSON reads the "id" member of one candidate object and applies
529	// the shared cluster-identity rule. A missing member or a non-string value is
530	// a JSON decoding problem with its own reason; an empty or duplicate ID is
531	// reported by the shared rule exactly as for a directly constructed config.
532	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
533		v, ok := obj["id"]
534		if !ok {
535			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
536		}
537		id, ok := v.(string)
538		if !ok {
539			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
540		}
541		if err := ids.check(index, id); err != nil {
542			return "", err
543		}
544		return id, nil
545	}
546	
547	// parseConditions reads the optional include/exclude field from the decoded
548	// document. An absent field means "no conditions" (the same as an explicit
549	// empty array); a field that is present must be an array of condition
550	// objects. An explicit JSON null is a field type error — it must not be read
551	// as "no conditions", which would silently drop the filter the author wrote.
552	func parseConditions(doc map[string]any, field string) ([]LabelCondition, error) {
553		v, ok := doc[field]
554		if !ok {
555			return []LabelCondition{}, nil
556		}
557		raw, ok := v.([]any)
558		if !ok {
559			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
560		}
561		conds := make([]LabelCondition, 0, len(raw))
562		for i, item := range raw {
563			obj, ok := item.(map[string]any)
564			if !ok {
565				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
566			}
567			cond, err := labelsFromJSON(obj,
568				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
569				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
570			)
571			if err != nil {
572				return nil, err
573			}
574			if err := validateCondition(field, i, cond); err != nil {
575				return nil, err
576			}
577			conds = append(conds, cond)
578		}
579		return conds, nil
580	}
581	
582	// MakeReleasePlan selects available clusters, orders them by ID, and splits
583	// them into batches. When SpreadBy names a tag, each batch holds at most one
584	// cluster per value of that tag (its fault domain) and every selected cluster
585	// must carry the tag. It validates the input first and never mutates it.
586	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
587		if err := ValidateReleaseInput(in); err != nil {
588			return ReleasePlan{}, err
589		}
590		if len(in.Clusters) == 0 {
591			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
592		}
593	
594		selected := []string{}
595		excluded := []ExcludedCluster{}
596		for _, c := range in.Clusters {
597			switch {
598			case c.Disabled:
599				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
600			case matchesAny(c.Tags, in.Exclude):
601				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
602			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
603				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
604			default:
605				selected = append(selected, c.ID)
606			}
607		}
608	
609		sort.Strings(selected)
610		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
611	
612		if len(selected) == 0 {
613			var b strings.Builder
614			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
615			for _, e := range excluded {
616				b.WriteString("\n  ")
617				b.WriteString(e.ID)
618				b.WriteString("：")
619				b.WriteString(e.Reason)
620			}
621			return ReleasePlan{}, errors.New(b.String())
622		}
623	
624		var batches []Batch
625		if in.SpreadBy == "" {
626			batches = chunkBatches(selected, in.BatchSize)
627		} else {
628			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
629			if err != nil {
630				return ReleasePlan{}, err
631			}
632			batches = spreadBatches(selected, domains, in.BatchSize)
633		}
634	
635		return ReleasePlan{
636			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
637			Batches:  batches,
638			Excluded: excluded,
639		}, nil
640	}
641	
642	// chunkBatches splits the ascending IDs into batches of at most batchSize.
643	// Each batch's Clusters gets its own backing array: a subslice of selected
644	// would leave spare capacity pointing at the next batch's IDs, so a caller
645	// appending to one batch's list would overwrite the following batch.
646	func chunkBatches(selected []string, batchSize int) []Batch {
647		batches := []Batch{}
648		for i := 0; i < len(selected); i += batchSize {
649			end := i + batchSize
650			if end > len(selected) {
651				end = len(selected)
652			}
653			clusters := make([]string, end-i)
654			copy(clusters, selected[i:end])
655			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: clusters})
656		}
657		return batches
658	}
659	
660	// faultDomains maps every selected cluster ID to the exact value of its
661	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
662	// selected is ascending, so the smallest such ID is reported. An empty
663	// string tag value is a valid fault domain, distinct from a missing tag.
664	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
665		tagsByID := make(map[string]map[string]string, len(clusters))
666		for _, c := range clusters {
667			tagsByID[c.ID] = c.Tags
668		}
669		domains := make(map[string]string, len(selected))
670		for _, id := range selected {
671			v, ok := tagsByID[id][spreadBy]
672			if !ok {
673				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
674			}
675			domains[id] = v
676		}
677		return domains, nil
678	}
679	
680	// spreadBatches packs the ascending IDs into batches of at most batchSize
681	// with at most one cluster per fault domain in each batch. Each batch takes
682	// the smallest still-unscheduled IDs whose domains do not conflict with the
683	// batch; conflicting clusters are deferred to later batches, so a batch may
684	// be short only when no non-conflicting cluster remains. Every ID appears in
685	// exactly one batch and IDs stay ascending within a batch.
686	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
687		remaining := append([]string(nil), selected...)
688		batches := []Batch{}
689		for len(remaining) > 0 {
690			// The map never holds more entries than there are remaining clusters,
691			// so size it by them — never by batchSize, which is only an upper
692			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
693			used := make(map[string]struct{}, min(batchSize, len(remaining)))
694			batch := []string{}
695			deferred := []string{}
696			for _, id := range remaining {
697				d := domains[id]
698				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
699					used[d] = struct{}{}
700					batch = append(batch, id)
701				} else {
702					deferred = append(deferred, id)
703				}
704			}
705			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
706			remaining = deferred
707		}
708		return batches
709	}
710	
711	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
712		for _, cond := range conditions {
713			if matchesAll(tags, cond) {
714				return true
715			}
716		}
717		return false
718	}
719	
720	func matchesAll(tags map[string]string, cond LabelCondition) bool {
721		for k, v := range cond {
722			tv, ok := tags[k]
723			if !ok || tv != v {
724				return false
725			}
726		}
727		return true
728	}
729

