1	package darksafe
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	// This file is the automated regression net for multi-label EXCLUDE conditions
10	// in the offline release plan. The distinction it protects is the AND/OR
11	// structure of label matching (also documented in README "标签条件怎么匹配"):
12	//
13	//   - Within one condition object every key-value pair must match (AND): a
14	//     cluster is excluded by {"env":"prod","quarantine":"true"} only when it
15	//     carries BOTH pairs. Merely sharing one label is not a hit.
16	//   - Across the exclude array ANY one fully matched condition excludes (OR):
17	//     pairs satisfied in different conditions must never be stitched together
18	//     into a single hit.
19	//
20	// Every assertion is written against the published result of MakeReleasePlan
21	// — batches, the excluded list and, on the all-rejected path, the error —
22	// never against the internal matching helpers.
23	
24	// multiExcludeConditions are the two two-label exclude conditions used
25	// throughout this file: each must be satisfied wholesale.
26	func multiExcludeConditions() []LabelCondition {
27		return []LabelCondition{
28			{"env": "prod", "quarantine": "true"},
29			{"region": "west", "tier": "edge"},
30		}
31	}
32	
33	// exclusionRows reports, for every candidate, whether it appears in any batch
34	// and — if it does not — its exclusion reason. A candidate is present at most
35	// once either way.
36	type exclusionRows map[string]struct {
37		Selected bool
38		Reason   string
39	}
40	
41	func planRows(t *testing.T, plan ReleasePlan) exclusionRows {
42		t.Helper()
43		rows := exclusionRows{}
44		for _, b := range plan.Batches {
45			for _, id := range b.Clusters {
46				if _, dup := rows[id]; dup {
47					t.Fatalf("cluster %q appears more than once in the plan", id)
48				}
49				rows[id] = struct {
50					Selected bool
51					Reason   string
52				}{Selected: true}
53			}
54		}
55		for _, e := range plan.Excluded {
56			if _, dup := rows[e.ID]; dup {
57				t.Fatalf("cluster %q is both batched and recorded as excluded", e.ID)
58			}
59			rows[e.ID] = struct {
60				Selected bool
61				Reason   string
62			}{Reason: e.Reason}
63		}
64		return rows
65	}
66	
67	func (r exclusionRows) requireSelected(t *testing.T, id string) {
68		t.Helper()
69		row, ok := r[id]
70		if !ok {
71			t.Fatalf("cluster %q missing from the whole plan (neither batched nor excluded)", id)
72		}
73		if !row.Selected {
74			t.Fatalf("cluster %q must be released, but is excluded: %s", id, row.Reason)
75		}
76	}
77	
78	func (r exclusionRows) requireExcluded(t *testing.T, id, reason string) {
79		t.Helper()
80		row, ok := r[id]
81		if !ok {
82			t.Fatalf("cluster %q missing from the whole plan (neither batched nor excluded)", id)
83		}
84		if row.Selected {
85			t.Fatalf("cluster %q must be excluded (%s), but is batched", id, reason)
86		}
87		if row.Reason != reason {
88			t.Fatalf("cluster %q reason = %q, want %q", id, row.Reason, reason)
89		}
90	}
91	
92	// TestExclude_MultiLabelConditionRequiresAllPairs is the headline AND/OR
93	// regression. The two exclude conditions are
94	// {"env":"prod","quarantine":"true"} and {"region":"west","tier":"edge"}.
95	//
96	//   - partial-one  satisfies only env=prod of condition 1: no full hit.
97	//   - cross-pairs  satisfies env=prod (condition 1) and region=west
98	//     (condition 2) but neither quarantine=true nor tier=edge:
99	//     the two half-hits live in different conditions and must not
100	//     be combined into one exclusion.
101	//   - hit-one      fully satisfies condition 1 (plus an unrelated label).
102	//   - hit-two      fully satisfies condition 2.
103	//   - hit-both     fully satisfies BOTH conditions: still a single exclusion
104	//     record, reason 命中排除条件.
105	//   - unrelated    matches nothing either way and is released.
106	//
107	// Extra, unrelated tags must not change any of these outcomes; keys and values
108	// stay exact strings.
109	func TestExclude_MultiLabelConditionRequiresAllPairs(t *testing.T) {
110		in := ReleasePlanInput{
111			App:       "app",
112			Revision:  "r1",
113			Image:     "img",
114			BatchSize: 10,
115			Exclude:   multiExcludeConditions(),
116			Clusters: []Cluster{
117				{ID: "partial-one", Tags: map[string]string{"env": "prod"}},
118				{ID: "cross-pairs", Tags: map[string]string{"env": "prod", "region": "west"}},
119				{ID: "hit-one", Tags: map[string]string{
120					"env": "prod", "quarantine": "true", "team": "payments",
121				}},
122				{ID: "hit-two", Tags: map[string]string{
123					"region": "west", "tier": "edge", "note": "canary",
124				}},
125				{ID: "hit-both", Tags: map[string]string{
126					"env": "prod", "quarantine": "true",
127					"region": "west", "tier": "edge",
128				}},
129				{ID: "unrelated", Tags: map[string]string{"env": "dev", "region": "east"}},
130			},
131		}
132		plan, err := MakeReleasePlan(in)
133		if err != nil {
134			t.Fatal(err)
135		}
136	
137		rows := planRows(t, plan)
138		rows.requireSelected(t, "partial-one")
139		rows.requireSelected(t, "cross-pairs")
140		rows.requireSelected(t, "unrelated")
141		rows.requireExcluded(t, "hit-one", ReasonExcludeMatched)
142		rows.requireExcluded(t, "hit-two", ReasonExcludeMatched)
143		rows.requireExcluded(t, "hit-both", ReasonExcludeMatched)
144	
145		if len(plan.Excluded) != 3 {
146			t.Fatalf("excluded list = %+v, want exactly the three full hits", plan.Excluded)
147		}
148		// Unselected records keep the existing convention: ascending by ID, and a
149		// cluster fully matching two conditions still occurs exactly once.
150		wantExcluded := []ExcludedCluster{
151			{ID: "hit-both", Reason: ReasonExcludeMatched},
152			{ID: "hit-one", Reason: ReasonExcludeMatched},
153			{ID: "hit-two", Reason: ReasonExcludeMatched},
154		}
155		if !reflect.DeepEqual(plan.Excluded, wantExcluded) {
156			t.Fatalf("excluded = %+v, want %+v", plan.Excluded, wantExcluded)
157		}
158	
159		// Selected clusters keep the existing scheduling convention: ascending by
160		// ID in one batch; no excluded ID may leak into any batch.
161		wantBatches := []Batch{{Index: 1, Clusters: []string{
162			"cross-pairs", "partial-one", "unrelated",
163		}}}
164		if !reflect.DeepEqual(plan.Batches, wantBatches) {
165			t.Fatalf("batches = %+v, want %+v", plan.Batches, wantBatches)
166		}
167	}
168	
169	// TestExclude_MultiLabelOrderAndTagIrrelevance proves the AND/OR result does
170	// not depend on how the author writes the document: reordering the conditions,
171	// shuffling the pairs inside a condition and the tags inside a cluster, and
172	// adding unrelated labels must all yield byte-identical plans. This also pins
173	// exact key/value comparison ("ENV" vs "env", "true" vs " true", "west" vs
174	// "West") through the half-hit cases.
175	func TestExclude_MultiLabelOrderAndTagIrrelevance(t *testing.T) {
176		base := `{
177	  "app": "app", "revision": "r1", "image": "img", "batchSize": 10,
178	  "exclude": [
179	    {"env": "prod", "quarantine": "true"},
180	    {"region": "west", "tier": "edge"}
181	  ],
182	  "clusters": [
183	    {"id": "hit-both", "tags": {"env": "prod", "quarantine": "true", "region": "west", "tier": "edge"}},
184	    {"id": "cross-pairs", "tags": {"env": "prod", "region": "west"}},
185	    {"id": "hit-one", "tags": {"env": "prod", "quarantine": "true", "team": "payments"}},
186	    {"id": "partial-one", "tags": {"env": "prod"}},
187	    {"id": "unrelated", "tags": {"env": "dev", "region": "east"}}
188	  ]
189	}`
190		shuffled := `{
191	  "app": "app", "revision": "r1", "image": "img", "batchSize": 10,
192	  "exclude": [
193	    {"tier": "edge", "region": "west"},
194	    {"quarantine": "true", "env": "prod"}
195	  ],
196	  "clusters": [
197	    {"id": "unrelated", "tags": {"region": "east", "env": "dev", "extra": "x"}},
198	    {"id": "partial-one", "tags": {"env": "prod", "extra": "x"}},
199	    {"id": "hit-one", "tags": {"team": "payments", "quarantine": "true", "env": "prod"}},
200	    {"id": "cross-pairs", "tags": {"region": "west", "env": "prod", "extra": "x"}},
201	    {"id": "hit-both", "tags": {"tier": "edge", "region": "west", "quarantine": "true", "env": "prod"}}
202	  ]
203	}`
204		p1, err := MakeReleasePlan(parsePlan(t, base))
205		if err != nil {
206			t.Fatal(err)
207		}
208		p2, err := MakeReleasePlan(parsePlan(t, shuffled))
209		if err != nil {
210			t.Fatal(err)
211		}
212		if !reflect.DeepEqual(p1, p2) {
213			t.Fatalf("plans differ across order/extra-tag changes:\n %+v\n %+v", p1, p2)
214		}
215	
216		// Exact string comparison protects the boundary: superficially similar
217		// keys and values must not turn a half-hit into a full hit.
218		doc := `{
219	  "app": "app", "revision": "r1", "image": "img", "batchSize": 10,
220	  "exclude": [
221	    {"env": "prod", "quarantine": "true"},
222	    {"region": "west", "tier": "edge"}
223	  ],
224	  "clusters": [
225	    {"id": "case-key", "tags": {"ENV": "prod", "quarantine": "true"}},
226	    {"id": "case-val-env", "tags": {"env": "prod", "region": "West"}},
227	    {"id": "space-val", "tags": {"env": "prod", "quarantine": " true"}},
228	    {"id": "tier-diff", "tags": {"region": "west", "tier": "edge ", "env": "prod"}}
229	  ]
230	}`
231		plan, err := MakeReleasePlan(parsePlan(t, doc))
232		if err != nil {
233			t.Fatal(err)
234		}
235		rows := planRows(t, plan)
236		for _, id := range []string{"case-key", "case-val-env", "space-val", "tier-diff"} {
237			rows.requireSelected(t, id)
238		}
239	}
240	
241	// TestExclude_EmptyStringValueDistinctFromMissingKey pins the missing-tag vs
242	// empty-value distinction for multi-label EXCLUDE conditions: a condition
243	// demanding quarantine="" is fully matched only by a cluster that CARRIES the
244	// key with that exact empty value; a cluster without the key cannot match, even
245	// though a zero-value map lookup would return "". The condition's other key
246	// still has to match as well.
247	func TestExclude_EmptyStringValueDistinctFromMissingKey(t *testing.T) {
248		conds := []LabelCondition{{"quarantine": "", "env": "prod"}}
249		cases := map[string]struct {
250			tags   map[string]string
251			reason string // "" means selected
252		}{
253			"empty value full match": {
254				tags:   map[string]string{"env": "prod", "quarantine": ""},
255				reason: ReasonExcludeMatched,
256			},
257			"empty value with unrelated extra tag full match": {
258				tags:   map[string]string{"env": "prod", "quarantine": "", "team": "x"},
259				reason: ReasonExcludeMatched,
260			},
261			"key missing entirely": {
262				tags:   map[string]string{"env": "prod"},
263				reason: "", // selected: a missing key never equals a demanded ""
264			},
265			"empty value but the other key mismatches": {
266				tags:   map[string]string{"env": "dev", "quarantine": ""},
267				reason: "", // selected: AND requires env=prod too
268			},
269			"empty value and other key missing": {
270				tags:   map[string]string{"quarantine": ""},
271				reason: "",
272			},
273			"non-empty value is not the empty string": {
274				tags:   map[string]string{"env": "prod", "quarantine": "false"},
275				reason: "",
276			},
277		}
278		for name, tc := range cases {
279			t.Run(name, func(t *testing.T) {
280				in := ReleasePlanInput{
281					App:       "app",
282					Revision:  "r1",
283					Image:     "img",
284					BatchSize: 10,
285					Exclude:   conds,
286					// A companion cluster keeps the plan deliverable when c is
287					// excluded, so c's fate is observable in the result rows.
288					Clusters: []Cluster{
289						{ID: "c", Tags: tc.tags},
290						{ID: "keep", Tags: map[string]string{"env": "dev"}},
291					},
292				}
293				plan, err := MakeReleasePlan(in)
294				if err != nil {
295					t.Fatal(err)
296				}
297				rows := planRows(t, plan)
298				rows.requireSelected(t, "keep")
299				if tc.reason == "" {
300					rows.requireSelected(t, "c")
301				} else {
302					rows.requireExcluded(t, "c", tc.reason)
303				}
304			})
305		}
306	
307		// The JSON path agrees: present-but-empty excludes, absent key does not.
308		doc := `{
309	  "app": "app", "revision": "r1", "image": "img", "batchSize": 10,
310	  "exclude": [{"env": "prod", "quarantine": ""}],
311	  "clusters": [
312	    {"id": "has-empty", "tags": {"env": "prod", "quarantine": ""}},
313	    {"id": "no-key", "tags": {"env": "prod"}}
314	  ]
315	}`
316		plan, err := MakeReleasePlan(parsePlan(t, doc))
317		if err != nil {
318			t.Fatal(err)
319		}
320		rows := planRows(t, plan)
321		rows.requireExcluded(t, "has-empty", ReasonExcludeMatched)
322		rows.requireSelected(t, "no-key")
323	}
324	
325	// TestExclude_PriorityWithIncludeAndDisabled protects how the exclude
326	// decision interacts with the surrounding rules (priority 停用 → 排除 → 包含):
327	//   - both       matches an include condition AND a multi-label exclude
328	//     condition: exclude wins;
329	//   - off-hit    is disabled AND fully satisfies an exclude condition: the
330	//     reason stays 集群已停用, never 命中排除条件;
331	//   - not-inc    matches no exclude condition (only env=prod of the first
332	//     one) and also fails the include filter: it must not gain
333	//     release eligibility merely because exclusion did not hit —
334	//     its reason is 未命中包含条件;
335	//   - selected   passes both filters and is the sole released cluster.
336	func TestExclude_PriorityWithIncludeAndDisabled(t *testing.T) {
337		in := ReleasePlanInput{
338			App:       "app",
339			Revision:  "r1",
340			Image:     "img",
341			BatchSize: 10,
342			Include:   []LabelCondition{{"env": "prod"}},
343			Exclude:   multiExcludeConditions(),
344			Clusters: []Cluster{
345				{ID: "selected", Tags: map[string]string{"env": "prod", "region": "east"}},
346				{ID: "both", Tags: map[string]string{
347					"env": "prod", "quarantine": "true",
348				}},
349				{ID: "off-hit", Disabled: true, Tags: map[string]string{
350					"env": "prod", "quarantine": "true",
351				}},
352				{ID: "not-inc", Tags: map[string]string{"env": "dev", "region": "west"}},
353				{ID: "cross-pairs", Tags: map[string]string{"env": "prod", "region": "west"}},
354			},
355		}
356		plan, err := MakeReleasePlan(in)
357		if err != nil {
358			t.Fatal(err)
359		}
360		rows := planRows(t, plan)
361		rows.requireSelected(t, "selected")
362		rows.requireSelected(t, "cross-pairs") // env=prod satisfies include; no full exclude hit
363		rows.requireExcluded(t, "both", ReasonExcludeMatched)
364		rows.requireExcluded(t, "off-hit", ReasonDisabled)
365		rows.requireExcluded(t, "not-inc", ReasonIncludeNotMatched)
366	
367		wantExcluded := []ExcludedCluster{
368			{ID: "both", Reason: ReasonExcludeMatched},
369			{ID: "not-inc", Reason: ReasonIncludeNotMatched},
370			{ID: "off-hit", Reason: ReasonDisabled},
371		}
372		if !reflect.DeepEqual(plan.Excluded, wantExcluded) {
373			t.Fatalf("excluded = %+v, want %+v", plan.Excluded, wantExcluded)
374		}
375	}
376	
377	// TestExclude_AllCandidatesLoseEligibilityReturnsZeroPlan covers the complete
378	// failure result under multi-label exclude conditions: when every candidate
379	// loses eligibility the call returns a non-nil error and the zero-value plan,
380	// and the error preserves every candidate's reason exactly once, ascending by
381	// ID. Half-hits are deliberately included so that a broken AND (excluding on a
382	// single matching label) would change both the error and the plan: under the
383	// correct semantics the half-hit clusters are released through the include
384	// path here, so to force the all-rejected path they fail the include filter
385	// instead.
386	func TestExclude_AllCandidatesLoseEligibilityReturnsZeroPlan(t *testing.T) {
387		in := ReleasePlanInput{
388			App:       "app",
389			Revision:  "r1",
390			Image:     "img",
391			BatchSize: 2,
392			Include:   []LabelCondition{{"env": "prod"}},
393			Exclude:   multiExcludeConditions(),
394			Clusters: []Cluster{
395				// Sorted by ID the candidates are:
396				// e-cross  env=prod + region=west: half of EACH exclude condition
397				//          only. Include says env=prod → released, so exclude it
398				//          from this scenario by env=dev instead; it then fails
399				//          include with no full exclude hit.
400				{ID: "e-cross", Tags: map[string]string{"env": "dev", "region": "west"}},
401				{ID: "e-hit1", Tags: map[string]string{"env": "prod", "quarantine": "true"}},
402				{ID: "e-hit2", Tags: map[string]string{"region": "west", "tier": "edge"}},
403				{ID: "e-off", Disabled: true, Tags: map[string]string{
404					"region": "west", "tier": "edge",
405				}},
406				{ID: "e-partial", Tags: map[string]string{"env": "dev"}},
407			},
408		}
409		plan, err := MakeReleasePlan(in)
410		if err == nil {
411			t.Fatal("expected a non-nil error when every candidate loses eligibility")
412		}
413		assertZeroReleasePlan(t, plan)
414	
415		msg := err.Error()
416		want := allRejectedLibraryError(
417			"e-cross："+ReasonIncludeNotMatched,
418			"e-hit1："+ReasonExcludeMatched,
419			"e-hit2："+ReasonExcludeMatched,
420			"e-off："+ReasonDisabled,
421			"e-partial："+ReasonIncludeNotMatched,
422		)
423		if msg != want {
424			t.Fatalf("rejection error mismatch:\n got %q\nwant %q", msg, want)
425		}
426		// Every candidate must be accounted for exactly once.
427		for _, id := range []string{"e-cross", "e-hit1", "e-hit2", "e-off", "e-partial"} {
428			if strings.Count(msg, "\n  "+id+"：") != 1 {
429				t.Fatalf("candidate %q must appear exactly once in %q", id, msg)
430			}
431		}
432	}
433	
434	// TestExclude_UsableClustersStillProduceNormalPlan is the positive end-to-end
435	// guard: with available clusters around them, fully-hit clusters stay out of
436	// EVERY batch, the remaining clusters are scheduled with the existing
437	// ascending chunking convention, and exclusion records stay ascending by ID.
438	func TestExclude_UsableClustersStillProduceNormalPlan(t *testing.T) {
439		in := ReleasePlanInput{
440			App:       "app",
441			Revision:  "r1",
442			Image:     "img",
443			BatchSize: 2,
444			Exclude:   multiExcludeConditions(),
445			Clusters: []Cluster{
446				{ID: "k1"},
447				{ID: "k2", Tags: map[string]string{"env": "prod", "quarantine": "true"}},
448				{ID: "k3", Tags: map[string]string{"env": "prod"}},
449				{ID: "k4", Tags: map[string]string{"region": "west", "tier": "edge"}},
450				{ID: "k5", Tags: map[string]string{"env": "prod", "region": "west"}},
451			},
452		}
453		plan, err := MakeReleasePlan(in)
454		if err != nil {
455			t.Fatal(err)
456		}
457		wantBatches := []Batch{
458			{Index: 1, Clusters: []string{"k1", "k3"}},
459			{Index: 2, Clusters: []string{"k5"}},
460		}
461		if !reflect.DeepEqual(plan.Batches, wantBatches) {
462			t.Fatalf("batches = %+v, want %+v", plan.Batches, wantBatches)
463		}
464		wantExcluded := []ExcludedCluster{
465			{ID: "k2", Reason: ReasonExcludeMatched},
466			{ID: "k4", Reason: ReasonExcludeMatched},
467		}
468		if !reflect.DeepEqual(plan.Excluded, wantExcluded) {
469			t.Fatalf("excluded = %+v, want %+v", plan.Excluded, wantExcluded)
470		}
471	
472		// Spread batching must exclude before fault domains matter: the two
473		// excluded clusters carry no zone tag, yet the plan still succeeds.
474		in.SpreadBy = "zone"
475		for _, id := range []string{"k1", "k3", "k5"} {
476			for i := range in.Clusters {
477				if in.Clusters[i].ID == id {
478					in.Clusters[i].Tags = setZone(in.Clusters[i].Tags, id)
479				}
480			}
481		}
482		plan, err = MakeReleasePlan(in)
483		if err != nil {
484			t.Fatalf("excluded clusters need no fault-domain tag: %v", err)
485		}
486		if got := batchIDs(plan); strings.Join(got, "|") != "k1,k3|k5" {
487			t.Fatalf("spread batches = %v, want [k1 k3]|[k5]", got)
488		}
489	}
490	
491	// setZone returns a copy of tags carrying a deterministic zone value per ID.
492	func setZone(tags map[string]string, id string) map[string]string {
493		out := make(map[string]string, len(tags)+1)
494		for k, v := range tags {
495			out[k] = v
496		}
497		out["zone"] = "z-" + id
498		return out
499	}
